import sys, json
sys.path.append('storage/shared/atlas/tools')
import rebuild_index_auto_from_curated as reb
import ci_validate

if __name__ == "__main__":
    # Rebuild index_auto.json
    # (Importing module executes only if called as script; call functions directly)
    # Re-run its main logic by re-executing file content conveniently:
    # We'll duplicate minimal logic inline for safety.
    import os, datetime as dt

    def load_index(path):
        if not os.path.exists(path): return {"entries": [], "updated": None}
        with open(path, "r", encoding="utf-8") as f:
            try: return json.load(f)
            except Exception: return {"entries": [], "updated": None}

    def norm_entries(d):
        ents = d.get("entries", [])
        out = []
        for e in ents:
            if isinstance(e, dict) and "entry_path" in e: out.append({"entry_path": e["entry_path"]})
            elif isinstance(e, dict) and "path" in e:     out.append({"entry_path": e["path"]})
            elif isinstance(e, str):                      out.append({"entry_path": e})
        return out

    def save_index(path, entries):
        data = {"entries": entries, "generated": dt.datetime.utcnow().isoformat() + "Z"}
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)

    CURATED = "storage/shared/atlas/edges/index.json"
    AUTO    = "storage/shared/atlas/edges/index_auto.json"

    curated = norm_entries(load_index(CURATED))
    auto    = norm_entries(load_index(AUTO))
    seen = {e["entry_path"]: e for e in auto}
    for e in curated: seen[e["entry_path"]] = e
    merged = sorted(seen.values(), key=lambda x: x["entry_path"])
    save_index(AUTO, merged)

    out = ci_validate.run()
    print(json.dumps({
        "status": "ok",
        "auto_entries": len(merged),
        "ci_entries_found": out.get("entries_found"),
        "ci_ok": out.get("ok"),
        "ci_with_errors": out.get("with_errors"),
        "report_json": "storage/shared/atlas/edges/ci_validation_report.json",
        "report_txt": "storage/shared/atlas/edges/ci_validation_report.txt"
    }))
